"""Execute actual full-package TV discovery and system activity/service/input resolution."""
from pathlib import Path
import subprocess,tempfile
sources={
'android/content/ComponentName.java':'''package android.content;public class ComponentName {final String pkg,name;public ComponentName(String p,String n){pkg=p;name=n;}public String getPackageName(){return pkg;}public String flattenToString(){return pkg+"/"+name;}public static ComponentName unflattenFromString(String s){int at=s.indexOf('/');return at<1?null:new ComponentName(s.substring(0,at),s.substring(at+1));}}''',
'android/content/Intent.java':'''package android.content;public class Intent {public static final String ACTION_MAIN="main",ACTION_VIEW="view";public String action,pkg,data;public ComponentName component;public Intent(String a){action=a;}public Intent(String a,String d){action=a;data=d;}public Intent setPackage(String p){pkg=p;return this;}public Intent setComponent(ComponentName c){component=c;return this;}public ComponentName resolveActivity(android.content.pm.PackageManager pm){return action.equals("view")||action.equals("yandex.intent.action.TV_CHANNEL")&&"yandex".equals(pkg)?new ComponentName("player","Screen"):null;}}''',
'android/content/Context.java':'''package android.content;public class Context {public static final String TV_INPUT_SERVICE="tv";public final android.content.pm.PackageManager pm=new android.content.pm.PackageManager();public final android.media.tv.TvInputManager manager=new android.media.tv.TvInputManager();public android.content.pm.PackageManager getPackageManager(){return pm;}public Object getSystemService(String n){return manager;}public String getPackageName(){return "io.tvos";}public int checkSelfPermission(String p){return -1;}}''',
'android/content/pm/ApplicationInfo.java':'package android.content.pm;public class ApplicationInfo {public String label;public CharSequence loadLabel(PackageManager p){return label;}}',
'android/content/pm/ActivityInfo.java':'package android.content.pm;public class ActivityInfo {public String name,permission;public boolean exported=true,enabled=true;}',
'android/content/pm/ServiceInfo.java':'package android.content.pm;public class ServiceInfo {public String name,packageName;}',
'android/content/pm/PackageInfo.java':'package android.content.pm;public class PackageInfo {public String packageName;public ApplicationInfo applicationInfo;public ActivityInfo[] activities;public ServiceInfo[] services;}',
'android/content/pm/PackageManager.java':'''package android.content.pm;import java.util.*;public class PackageManager {public static final int GET_ACTIVITIES=1,GET_SERVICES=4,PERMISSION_GRANTED=0;public final List<PackageInfo> packages=new ArrayList<>();public List<PackageInfo> getInstalledPackages(int flags){if(flags!=0)throw new AssertionError();return packages;}public PackageInfo getPackageInfo(String pkg,int flags)throws NameNotFoundException {for(PackageInfo p:packages)if(p.packageName.equals(pkg))return p;throw new NameNotFoundException();}public ActivityInfo getActivityInfo(android.content.ComponentName c,int flags)throws NameNotFoundException {PackageInfo p=getPackageInfo(c.getPackageName(),flags);if(p.activities!=null)for(ActivityInfo a:p.activities)if(c.flattenToString().endsWith("/"+a.name))return a;throw new NameNotFoundException();}public static class NameNotFoundException extends Exception {private static final long serialVersionUID=1;}}''',
'android/media/tv/TvInputManager.java':'package android.media.tv;import java.util.*;public class TvInputManager {public final List<TvInputInfo> inputs=new ArrayList<>();public List<TvInputInfo> getTvInputList(){return inputs;}}',
'android/media/tv/TvInputInfo.java':'package android.media.tv;public class TvInputInfo {public String id;public boolean passthrough;public android.content.pm.ServiceInfo service;public String getId(){return id;}public android.content.pm.ServiceInfo getServiceInfo(){return service;}public boolean isPassthroughInput(){return passthrough;}public CharSequence loadLabel(android.content.Context c){return "TV Input";}}',
'android/media/tv/TvContract.java':'package android.media.tv;public class TvContract {public static String buildChannelUriForPassthroughInput(String id){return "passthrough:"+id;}public static String buildChannelsUriForInput(String id){return "channels:"+id;}}',
'io/tvos/AppLog.java':'package io.tvos;class AppLog {static void w(String s){}}',
'io/tvos/AppLaunch.java':'package io.tvos;class AppLaunch {static android.content.Intent launchIntent(android.content.pm.PackageManager pm,String pkg){return pkg.equals("normal")?new android.content.Intent("launcher"):null;}}',
'io/tvos/TargetsTest.java':'''package io.tvos;import android.content.*;import android.content.pm.*;import android.media.tv.*;import java.util.*;class TargetsTest {static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static PackageInfo add(Context c,String pkg){PackageInfo p=new PackageInfo();p.packageName=pkg;p.applicationInfo=new ApplicationInfo();p.applicationInfo.label=pkg;c.pm.packages.add(p);return p;}public static void main(String[] args){Context c=new Context();add(c,"io.tvos");add(c,"normal");add(c,"yandex");PackageInfo hidden=add(c,"hidden");ActivityInfo activity=new ActivityInfo();activity.name="hidden.Screen";hidden.activities=new ActivityInfo[]{activity};PackageInfo daemon=add(c,"daemon");ServiceInfo service=new ServiceInfo();service.name="TunerService";service.packageName="daemon";daemon.services=new ServiceInfo[]{service};TvInputInfo tuner=new TvInputInfo();tuner.service=service;tuner.id="daemon/TunerService/HW1";c.manager.inputs.add(tuner);List<String[]> list=LiveTvTargets.load(c);Set<String> keys=new HashSet<>();for(String[] entry:list)check(keys.add(entry[0]),"no duplicate target identities");check(!keys.contains("hidden")&&!keys.contains("daemon")&&!keys.contains("service:daemon/TunerService")&&!keys.contains("activity:hidden/hidden.Screen")&&keys.contains("normal")&&keys.contains("yandex")&&keys.contains("input:"+tuner.id)&&!keys.contains("io.tvos"),"only launchable apps, action-only TV and registered TV inputs are listed");check(LiveTvTargets.intent(c,"yandex").action.equals("yandex.intent.action.TV_CHANNEL"),"Yandex action-only app works without launcher allowlist");check(LiveTvTargets.intent(c,"normal").action.equals("launcher"),"normal app keeps launcher behavior");check(LiveTvTargets.intent(c,"hidden").component.flattenToString().equals("hidden/hidden.Screen"),"hidden package finds exported screen");check(LiveTvTargets.intent(c,"service:daemon/TunerService").data.equals("channels:"+tuner.id),"TV service resolves through tuner input rather than startService");tuner.passthrough=true;check(LiveTvTargets.intent(c,"input:"+tuner.id).data.equals("passthrough:"+tuner.id),"explicit HDMI input is preserved");check(LiveTvTargets.intent(c,"activity:hidden/hidden.Screen")!=null,"explicit activity choice works");activity.permission="signature.only";check(LiveTvTargets.intent(c,"activity:hidden/hidden.Screen")==null,"protected activity is not silently started");activity.permission=null;activity.exported=false;check(LiveTvTargets.intent(c,"activity:hidden/hidden.Screen")==null,"private activity refused");c.manager.inputs.clear();check(LiveTvTargets.intent(c,"service:daemon/TunerService")==null,"service without a UI or TV input remains unsupported");check(LiveTvTargets.intent(c,"input:removed")==null&&LiveTvTargets.intent(c,"activity:bad")==null,"removed input and malformed target recover safely");System.out.println("PASS: actual system package/activity/service/input discovery, action-only Yandex TV, permissions and removed targets");}}'''
}
sources['io/tvos/LiveTvTargets.java']=Path('app/src/io/tvos/LiveTvTargets.java').read_text()
with tempfile.TemporaryDirectory() as tmp:
 root=Path(tmp)
 for name,text in sources.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
 subprocess.run(['java','com.sun.tools.javac.Main','--release','8','-Xlint:all,-options','-Werror','-d',tmp,*map(str,root.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',tmp,'io.tvos.TargetsTest'],check=True,timeout=15)
